Taking expectation on $\mathbf{w}^*$, under Assumption 4.1, we have:
    \begin{itemize}[leftmargin=*,nosep]
        \item For multiplicative quantization, under the conditions in Theorem 4.2,
        \begin{equation*}
            \mathbb{E}\left[\mathcal{E}(\overline{\mathbf{w}}_N)\right]\lesssim\frac{\epsilon_d}{1+\epsilon_d}+d^{1-a}+N^{1/a-1}(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)^{1/a}.
        \end{equation*}
        \item For additive quantization, under the conditions in Corollary 4.1,
        \begin{equation*}
            \begin{aligned}
                \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]\lesssim &\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\left(1+\frac{(d^a\epsilon_d)^2}{1+d^a\epsilon_d}\right)d^{1-a}+\frac{d^a\epsilon_d}{1+d^a\epsilon_d}\\
                +&\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)(1+d^a\epsilon_d)^{1/a}N^{1/a-1}.
            \end{aligned}
        \end{equation*}
    \end{itemize}

Under Assumption 3.1, 3.2, 3.3 and 3.4, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-additive, and the stepsize satisfies $\gamma < \frac{1}{\alpha_B [\mathrm{tr}(\mathbf{H})+d\epsilon_d]}$, then
    \begin{equation*}
        \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{ VarErr}+\mathrm{BiasErr},
    \end{equation*}
    where
    \begin{align*}
            &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{\lambda_d+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\lesssim\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
            &\mathrm{VarErr}\lesssim \frac{\alpha_B\|\mathbf{w}^*\|_\mathbf{H}^2+\frac{\sigma^2+\epsilon_o+\epsilon_a}{B}+\alpha_B \epsilon_p[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}{1-\gamma\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\right).
    \end{align*}

Under Assumption 3.1, 3.2, 3.3 and 3.4, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, and the stepsize satisfies $\gamma < \frac{1}{ \alpha_B (1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)\mathrm{tr}(\mathbf{H})}$, then the excess risk can be upper bounded as follows.
    \begin{equation*}
        \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{VarErr}+\mathrm{BiasErr},
    \end{equation*}
    where
    \begin{equation*}
        \begin{aligned}
            &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{1+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\lesssim\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
            &\mathrm{VarErr}\lesssim\left(\frac{k^*}{N}+N\gamma^2(1+\epsilon_d)^2\sum_{i>k^*}\lambda_i^2\right) \frac{\frac{(1+\epsilon_o)\sigma^2}{B}+\alpha_B(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\left\|\mathbf{w}^*\right\|_\mathbf{H}^2}{1-\gamma\alpha_B(1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)\mathrm{tr}\left(\mathbf{H}\right)}.
        \end{aligned}
    \end{equation*}

To ensure that $\mathbb E[\mathcal E(\overline{\mathbf w}_N)]\lesssim R_0$, conditions on the quantization error are as follows:
\begin{itemize}[leftmargin=*,nosep]
\item For multiplicative quantization, under the conditions in Theorem 4.2, we require
    \begin{equation*}
        \epsilon_d\lesssim 1\wedge \frac{R_0}{\|\mathbf{w}^*\|_{\mathbf{H}}^2},\quad\epsilon_o,\epsilon_a,\epsilon_p \lesssim  \left(\frac{\sigma^2}{B\alpha_B\|\mathbf{w}^*\|_\mathbf{H}^2}+\frac{\frac{1}{N\gamma}\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}{\|\mathbf{w}^*\|_\mathbf{H}^2}\right)\wedge 1.
    \end{equation*}
\item For additive quantization, under the conditions in Corollary 4.1, we require
\begin{gather*}
        \epsilon_d\lesssim \sqrt{\frac{\frac{k_0^*}{N}+N\gamma^2\cdot\sum_{i>k_0^*}\lambda_i^2}{N\gamma^2(d-k_0^*)}}\wedge \frac{R_0\lambda_d}{\|\mathbf{w}^*\|_{\mathbf{H}}^2},\quad \epsilon_a,\epsilon_o\lesssim \sigma^2+B\alpha_B\left(\frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2\right), \\ 
        \epsilon_p\lesssim \frac{\sigma^2}{B\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}+\frac{\frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}{\mathrm{tr}(\mathbf{H})+d\epsilon_d}.
    \end{gather*}
\end{itemize}

Consider general quantization. Denote $\mathbf{D}_1^{\mathbf{H}}=\mathbf{D}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{H}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{D}$, $\mathbf{D}_2^{\mathbf{H}}=\mathbf{H}(\mathbf{H}^{(q)})^{-1}\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\mathbf{D}(\mathbf{H}^{(q)})^{-1}\mathbf{H}$. Under Assumption 3.1, 3.2, 3.3 and 3.4, if the stepsize $\gamma < \frac{1}{\alpha_B \mathrm{tr}(\mathbf{H}^{(q)})}$, then it holds,
    \begin{equation*}
        \mathbb{E}[\mathcal E(\overline{\mathbf{w}}_N)]\leq 2\mathrm{VarErr}+2\mathrm{BiasErr}+\mathrm{ApproxErr},

    \end{equation*}
    where
    \begin{equation*}
        \begin{aligned}
            &\mathrm{VarErr}\leq\frac{2\alpha_B\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)+{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),\\
            &\mathrm{BiasErr}\leq\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
            &\mathrm{ApproxErr}\leq\left\|\mathbf{w}^*\right\|_{\mathbf{D}_1^{\mathbf{H}}}^2+\|\mathbf{w}^*\|_{\mathbf{D}_2^\mathbf{H}}^2,


        \end{aligned}
    \end{equation*}
    with ${\sigma_G^{(q)}}^2=\frac{\sigma^2+\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}+\alpha_B\sup_t\mathbb{E}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right)\right]$.

Under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
    \begin{equation*}
        \begin{aligned}
            R_N^{(0)}/2 \leq &\frac{2\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
            +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\\
            +& \frac{{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),
        \end{aligned}
    \end{equation*}
    where $k^*=\max\left\{k: \lambda_k^{(q)} \geq \frac{1}{N\gamma}\right\}$ and
    \begin{gather*}
        {\sigma_G^{(q)}}^2=\frac{\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}\\
        +\alpha_B\sup_t\mathbb{E}_{\mathbf{w}_{t-1}}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top \big| \mathbf{w}_{t-1}\right]\right)\right]
        +\frac{\sigma^2}{B}.
    \end{gather*}

Under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4, if the stepsize satisfies $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then
    \begin{equation*}
        \begin{aligned}
            R_N^{(0)}/2\leq & \frac{2(1+\tilde{\epsilon})\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
            +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\\
            +&\frac{{\sigma_M^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),
        \end{aligned}
    \end{equation*}
    where $k^*=\max\left\{k: \lambda_k^{(q)} \geq \frac{1}{N\gamma}\right\}$ and
    \begin{gather*}
        \tilde{\epsilon}=8\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+4\epsilon_p+4\epsilon_a(1+\epsilon_p),\\
        {\sigma_M^{(q)}}^2=\frac{(1+4\epsilon_o)\sigma^2}{B} + \frac{\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d}\alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+2\epsilon_p \right).
    \end{gather*}

If there exists $\epsilon_d$ such that $\mathcal{Q}_d$ is $\epsilon_d$-multiplicative, under the assumptions and notations in Lemma A.3, 
    \begin{equation*}
        \mathrm{ApproxErr}\leq \frac{\epsilon_d^2}{2(1+\epsilon_d)^2}\|\mathbf{w}^*\|_\mathbf{H}^2+\frac{\epsilon_d}{(1+\epsilon_d)^2}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2.
    \end{equation*}

If there exists $\epsilon_d$ such that $\mathcal{Q}_d$ is $\epsilon_d$-additive, under the assumptions and notations in Lemma A.3, 
    \begin{equation*}
        \mathrm{ApproxErr}\leq \frac{\epsilon_d^2}{2(\lambda_d+\epsilon_d)^2}\|\mathbf{w}^*\|_\mathbf{H}^2+\frac{\lambda_1\epsilon_d}{(\lambda_d+\epsilon_d)(\lambda_1+\epsilon_d)}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2.
    \end{equation*}

Under Assumption 3.1 and Assumption 3.2, if the stepsize $\gamma<\frac{1}{{\lambda}_1^{(q)}}$,
    \begin{equation*}
        \begin{aligned}
            \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]=&\underbrace{\frac{1}{2}\langle\mathbf{H},\mathbb{E}[\overline{\boldsymbol{\eta}}_N\otimes\overline{\boldsymbol{\eta}}_N]\rangle}_{R_N}+\mathrm{ApproxErr},
        \end{aligned}
    \end{equation*}
    where
    \begin{equation*}
        \begin{aligned}
            \mathrm{ApproxErr}=&\frac{1}{2}\langle\mathbf{H},({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\otimes({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\rangle\\
            +&\left({\mathbf{w}^{(q)}}^*\right)^\top\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*.
        \end{aligned}
    \end{equation*}

Under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4, if the stepsize satisfies $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then
    \begin{equation*}
        \begin{aligned}
            \mathrm{bias}\leq & \frac{2(1+\tilde{\epsilon})\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
            +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2.
        \end{aligned}
    \end{equation*}

Under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4, if the stepsize satisfies $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then
    \begin{equation*}
        \begin{aligned}
            \mathrm{variance}\leq  \frac{{\sigma_M^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right).
        \end{aligned}
    \end{equation*}

Under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
    \begin{equation*}
        \begin{aligned}
            \mathrm{bias}
            \leq & \frac{2\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
            +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2.
        \end{aligned}
    \end{equation*}

Under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
    \begin{equation*}
        \begin{aligned}
            \mathrm{variance}\leq  \frac{{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right).
        \end{aligned}
    \end{equation*}

For $1 \leq t\leq N$, under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4, if $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
     S_t}
    \begin{equation*}
         \mathcal{M}_B^{(q)} \circ \mathbf{S}_t \preceq \frac{\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t\right]\circ\mathbf{B}_0\right)}{\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}.
    \end{equation*}

For $1 \leq t\leq N$,
    \begin{equation*}
        \mathbf{S}_t \preceq (\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}+\gamma^{2}\mathcal{M}_B^{(q)}\circ\mathbf{S}_{N}+\mathbf{B}_{0}.
    \end{equation*}

Under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then
    \begin{equation*}
        R_N^{(0)}/2\leq \underbrace{\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{B}_t^{(M)}\right\rangle}_{\mathrm{bias}}+\underbrace{\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{C}_t^{(M)}\right\rangle}_{\mathrm{variance}},
    \end{equation*}
    where
    \begin{equation*}
        \mathbf{B}_t^{(M)}:=(\mathcal{I}-\gamma\mathcal{T}_B^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})^t \circ \mathbf{B}_0^{(M)}, \quad \mathbf{B}_0^{(M)}=\mathbb{E}\left[\boldsymbol{\eta}_0 \otimes \boldsymbol{\eta}_0\right].
    \end{equation*}
    \begin{equation*}
        \mathbf{C}_t^{(M)}: = (\mathcal{I}-\gamma \mathcal{T}_B^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})\circ\mathbf{C}_{t-1}^{(M)}+\gamma^2 {\sigma_M^{(q)}}^2\mathbf{H}^{(q)}, \quad \mathbf{C}_0^{(M)}=0.
    \end{equation*}

Under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4,
    \begin{equation*}
        R_N^{(0)}/2\leq \underbrace{\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{B}_t\right\rangle}_{\mathrm{bias}}+\underbrace{\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{C}_t\right\rangle}_{\mathrm{variance}},
    \end{equation*}
    where
    \begin{equation*}
        \mathbf{B}_t:=(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^t \circ \mathbf{B}_0, \quad \mathbf{B}_0=\mathbb{E}\left[\boldsymbol{\eta}_0 \otimes \boldsymbol{\eta}_0\right].
    \end{equation*}
    \begin{equation*}
        \mathbf{C}_t := (\mathcal{I}-\gamma \mathcal{T}_B^{(q)})\circ\mathbf{C}_{t-1}+\gamma^2 {\sigma_G^{(q)}}^2\mathbf{H}^{(q)},\quad \mathbf{C}_0=\boldsymbol{0}.
    \end{equation*}

Under Assumption 3.1 and Assumption 3.2,
    \begin{equation*}
        R_N^{(0)}\leq \frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t]\right\rangle.
    \end{equation*}

Under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4,
    \begin{gather*}
            \mathbf{C}_t
            \preceq \mathbb{E}\left[\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{C}_{t-1}\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right]+\gamma^2 {\sigma_G^{(q)}}^2\mathbf{H}^{(q)},\\
            \mathbf{B}_t
            = \mathbb{E}\left[\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{B}_{t-1}\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right],
    \end{gather*}
    where
    \begin{equation*}
        \begin{aligned}
            {\sigma_G^{(q)}}^2=&\frac{\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}\\
            +&\alpha_B\sup_t\mathbb{E}_{\mathbf{w}_{t-1}}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top \big| \mathbf{w}_{t-1}\right]\right)\right]
        +\frac{\sigma^2}{B},
        \end{aligned}
    \end{equation*}
    with $\mathbf{a}_t=\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1}),\ \mathbf{o}_t=\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)$ and $\|\cdot\|$ denoting the spectral norm.

If there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then under Assumption 3.1, Assumption 3.2, Assumption 3.3, and Assumption 3.4, it holds
    \begin{equation*}
        \begin{aligned}
            \mathbf{C}_t
            \preceq&\mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{C}_{t-1}\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right]\\
            +&\tilde{\epsilon}\mathbb{E}\left[\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top {\mathcal{Q}_d(\mathbf{X})}(\mathbf{B}_{t-1}+\mathbf{C}_{t-1})\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top\mathcal{Q}_d(\mathbf{X})\right]
            +\gamma^2 {\sigma_M^{(q)}}^2\mathbf{H}^{(q)},\\
            \mathbf{B}_t=& \mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{B}_{t-1}\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right],
        \end{aligned}
    \end{equation*}
    where
    \begin{gather*}
            \tilde{\epsilon}=8\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+4\epsilon_p+4\epsilon_a(1+\epsilon_p),\\
            {\sigma_M^{(q)}}^2=\frac{(1+4\epsilon_o)\sigma^2}{B} + \frac{\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d}\alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+2\epsilon_p \right).
    \end{gather*}

\begin{equation*}
        \boldsymbol{\eta}_t = \left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t) \right)\boldsymbol{\eta}_{t-1}+\gamma\frac{1}{B}{\mathcal{Q}_d(\mathbf{X}_t)}^\top \left[\boldsymbol{\xi}_t+\boldsymbol{\epsilon}_t^{(o)}-\boldsymbol{\epsilon}_t^{(a)}-\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\epsilon}_{t-1}^{(p)}\right],
    \end{equation*}
    where the quantization errors are
    \begin{equation*}
